package com.careerai.backend.storage;

import org.springframework.core.io.Resource;

/**
 * Where uploaded resume bytes live. Paths are always generated by ResumeStorageService
 * ("{userId}/{random}.{ext}") and validated before they reach a store; the database row keeps
 * the same storage_path whichever store is used.
 *
 * Selected with app.storage.resume-provider (RESUME_STORAGE_PROVIDER):
 *   local    (default) files under app.storage.resume-dir — use a persistent disk/volume when deployed
 *   database bytes in the resume_file_blobs table of the application database
 */
public interface ResumeFileStore {

    /** Writes a new file; fails if the path already exists. */
    void write(String storagePath, byte[] bytes);

    /** Reads a file, or throws ResumeNotFoundException when it does not exist. */
    Resource read(String storagePath);

    /** Deletes a file if it exists (missing files are not an error). */
    void delete(String storagePath);

    /** Short provider name for logs ("local", "database"). */
    String name();
}
